#include <iostream>

int main() {
    // Chaining literals and arithmetic expressions
    std::cout << "(10.5 + 2 * 3) / (45 - 3.5) = "
              << (10.5 + 2 * 3) / (45 - 3.5) << std::endl;

    std::cout << "3.5 * 4 / 2 - 2.5 = "
              << (3.5 * 4 / 2 - 2.5) << std::endl;

    return 0;
}

#include <iostream>

// Demonstrating modular structure linked together in a translation unit
void reportPhase(const char* phaseName, int stepNumber) {
    std::cout << "Phase " << stepNumber << ": " << phaseName << std::endl;
}

int main() {
    reportPhase("Preprocessing (#include directive expansion)", 1);
    reportPhase("Compilation (source code translated to object machine code)", 2);
    reportPhase("Linking (combining object code with standard libraries)", 3);
    reportPhase("Execution (operating system runs the final binary)", 4);
    return 0;
}

